// Copies the static demo's stylesheet and product photos into the React app. The demo is fixtures/demo/index.html
// with its photos beside it in fixtures/demo/assets/products (the web container mounts them as /legacy/index.html
// and /legacy/assets):
//
//   src/styles/legacy.gen.css  the demo's stylesheet, so React pages keep the same look and class names
//   public/assets/products/    the product photos
//
// Runs before `npm run dev`, `npm run build` and `npm test`. Generated files are not committed. The demo's static
// assets (logos, icons) are in src/ui/assets.gen.ts (scripts/dump-assets.mjs, committed).
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const candidates = [process.env.LEGACY_HTML, resolve(web, '../../fixtures/demo/index.html'), '/legacy/index.html'].filter(Boolean);
const htmlPath = candidates.find((p) => existsSync(p));
if (!htmlPath) throw new Error('index.html not found; looked in ' + candidates.join(', '));

const genCss = join(web, 'src/styles/legacy.gen.css');
if (existsSync(genCss) && statSync(genCss).mtimeMs >= statSync(htmlPath).mtimeMs && !process.argv.includes('--force')) {
  console.log('[styles] up to date');
  process.exit(0);
}

const style = /<style>([\s\S]*?)<\/style>/.exec(readFileSync(htmlPath, 'utf8'))?.[1];
if (!style) throw new Error('could not find the <style> block in ' + htmlPath);
mkdirSync(dirname(genCss), { recursive: true });
writeFileSync(genCss, '/* GENERATED by scripts/extract-styles.mjs from index.html. Do not edit. */\n' + style);

// the photos sit beside the demo, where its <img src="assets/products/..."> finds them
const photos = resolve(dirname(htmlPath), 'assets/products');
if (existsSync(photos)) {
  const out = join(web, 'public/assets/products');
  mkdirSync(out, { recursive: true });
  for (const f of readdirSync(photos)) if (/\.(webp|png|jpe?g)$/i.test(f)) copyFileSync(join(photos, f), join(out, f));
}
console.log(`[styles] ${htmlPath} -> legacy.gen.css (${(style.length / 1024) | 0} KB)`);
